/** Decorative artwork: the containing key button should provide its accessible letter label. */
export function LogoKeyGlyph({ letter, variant = "letter", className = "" }: LogoKeyGlyphProps) {
  const glyph = GLYPHS[variant === "emblem" && letter === "K" ? "emblem" : letter];
  return (
    <svg
      className={`${styles.glyph} ${className}`}
      viewBox={glyph.viewBox}
      preserveAspectRatio="xMidYMid meet"
      aria-hidden="true"
      focusable="false"
      data-logo-letter={letter}
      data-logo-variant={variant === "emblem" && letter === "K" ? "emblem" : "letter"}
    >
      {glyph.paths.map((path, index) => <path key={index} d={path.d} transform={path.transform} fill={path.fill} />)}
    </svg>
  );
}
